const { seg, lerp, eo, eio } = kit;
/* The end card. It opens on the stack as the build scene left it, the tiles drop
   away onto the hero gradient, the NUCLEUX wordmark glides from its slot to the
   centre (the intro's glide, reversed), then "Start exploring" under it and the
   calls to action:
   Explore nucleux.in. Held to the end. */
const PI2 = Math.PI * 2;
const bez = (x1, y1, x2, y2) => (x) => {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  let lo = 0, hi = 1, u = x;
  for (let i = 0; i < 22; i++) { u = (lo + hi) / 2; if (3 * (1 - u) * (1 - u) * u * x1 + 3 * (1 - u) * u * u * x2 + u * u * u < x) lo = u; else hi = u; }
  return 3 * (1 - u) * (1 - u) * u * y1 + 3 * (1 - u) * u * u * y2 + u * u * u;
};
const GLIDE = bez(0.65, 0, 0.35, 1), RISE = bez(0.25, 0.1, 0.25, 1);
const T = { drop: [0, 0.7], aurora: [0.2, 1.0], glide: [0.35, 1.55], words: 1.25, sub: 1.65, cta: [1.9] };
/* the hero gradient, as in the intro */
const FIELDS = [
  ['161 129 255', 0.62, 0.34, 0.11, 560, 430, 0.0],
  ['127 176 255', 0.62, 0.34, 0.11, 760, 660, 1.7],
  ['255 138 180', 0.58, 0.32, 0.10, 1360, 410, 3.1],
  ['255 178 140', 0.55, 0.30, 0.10, 1180, 680, 4.4],
];
const FW = 1000, FH = 770;
const MARK = { x: 750, y: 270, w: 420 };   /* smaller, so the line under it leads */
kit.scene('outro', {
  init(kit) {
    kit.css('.outro-aurora { position:absolute; inset:0; overflow:hidden } ' +
      '.outro-aurora span { position:absolute; left:0; top:0; width:' + FW + 'px; height:' + FH + 'px; border-radius:50% } ' +
      '.outro-scrim { position:absolute; inset:0; background:linear-gradient(180deg, rgba(251,251,250,.16) 0%, rgba(251,251,250,.28) 45%, rgba(251,251,250,.5) 82%, rgba(255,255,255,1) 100%) } ' +
      '.outro-mark { position:absolute; transform-origin:50% 50% } ' +
      '.outro-title { font-size:104px; line-height:1.04; letter-spacing:-0.035em; white-space:nowrap } ' +
      '.outro-sub { font-size:32px; line-height:1.5; color:color-mix(in srgb, var(--second) 80%, var(--ground)) } ' +
      '.outro-ctas { display:flex; gap:20px; align-items:center; margin-top:18px } .outro-ctas > * { margin:0 } ' +
      '.outro-btn { display:inline-flex; align-items:center; gap:14px; height:80px; padding:0 40px; border-radius:999px; background:var(--second); color:var(--ground); font-size:30px; font-weight:600; box-shadow:0 10px 30px -12px rgba(0,0,0,.35) }');
    const fields = FIELDS.map(([c, a, b, d]) =>
      '<span style="background:radial-gradient(closest-side, rgb(' + c + ' / ' + a + '), rgb(' + c + ' / ' + b + ') 40%, rgb(' + c + ' / ' + d + ') 70%, transparent)"></span>').join('');
    kit.stage.append(kit.h('<div class="ground"><div class="outro-aurora">' + fields + '</div><div class="outro-scrim"></div></div>'));
    this.aurora = kit.stage.querySelector('.outro-aurora').style;
    this.fields = [...kit.stage.querySelectorAll('.outro-aurora span')].map((el) => el.style);

    /* the stack as the build scene left it: tiles 1 and 2 covered, tile 3 on top, finished */
    this.t1 = window.HWF.tile(kit, 0, 3);
    window.HWF.cover(this.t1, 1);
    this.t2 = window.HWF.tile(kit, 1, 3.5);
    window.HWF.cover(this.t2, 1);
    this.t3 = window.HWF.tile(kit, 2, 6);

    const head = kit.h('<div class="words outro-head" style="left:160px;width:1600px;top:452px;align-items:center;text-align:center;gap:22px">' +
      '<h2 class="line outro-title">Start exploring</h2>' +
      '<p class="sub outro-sub">Agentic patterns and components, ready for your agent.</p>' +
      '<div class="outro-ctas"><span class="outro-btn">Explore nucleux.in →</span></div></div>');
    kit.stage.append(head);
    this.sub = head.querySelector('.outro-sub').style;
    this.btn = head.querySelector('.outro-btn').style;
    const line = head.querySelector('.outro-title');
    const words = line.textContent.split(' ');
    line.textContent = '';
    this.words = words.map((w, i) => {
      const sp = kit.el('span', { text: w, style: 'display:inline-block' });
      line.append(sp);
      if (i < words.length - 1) line.append(' ');
      return sp.style;
    });

    /* the wordmark, starting where every scene keeps it */
    const S = window.HWF.SLOT;
    const logo = kit.h('<div class="outro-mark" style="left:' + MARK.x + 'px;top:' + MARK.y + 'px;width:' + MARK.w + 'px">' + window.HWF.markSvg('outro') + '</div>');
    kit.stage.append(logo);
    this.logo = logo.style;
    const h = MARK.w * 24 / 120, sh = S.w * 24 / 120;
    this.from = { dx: S.x + S.w / 2 - (MARK.x + MARK.w / 2), dy: S.y + sh / 2 - (MARK.y + h / 2), k: S.w / MARK.w };
  },
  render(t) {
    /* the stack drops away */
    const d = eio(seg(t, T.drop[0], T.drop[1]));
    [this.t1, this.t2, this.t3].forEach((tile, i) => {
      const base = i < 2 ? 0.97 : 1.0146;
      tile.s.transform = 'translateY(' + (d * (760 + i * 40)).toFixed(1) + 'px) scale(' + base + ')';
      tile.s.opacity = (1 - eo(seg(t, T.drop[0] + 0.25, T.drop[1]))).toFixed(3);
    });
    /* the hero gradient comes up, drifting and breathing */
    this.aurora.opacity = (0.5 * eo(seg(t, T.aurora[0], T.aurora[1]))).toFixed(3);
    this.fields.forEach((s, i) => {
      const [, , , , x, y, ph] = FIELDS[i];
      const dx = 70 * Math.sin(PI2 * (t + ph) / 5.5), dy = 46 * Math.cos(PI2 * (t + ph) / 6.5);
      s.transform = 'translate(' + (x - FW / 2 + dx).toFixed(1) + 'px,' + (y - FH / 2 + dy).toFixed(1) + 'px) scale(' + (1 + 0.06 * Math.sin(PI2 * (t + ph) / 7)).toFixed(4) + ')';
      s.opacity = (0.82 + 0.18 * Math.sin(PI2 * (t + ph) / 4.5)).toFixed(3);
    });
    /* the wordmark glides from its slot to the centre, then breathes a little */
    const m = 1 - GLIDE(seg(t, T.glide[0], T.glide[1]));
    const k = lerp(1, this.from.k, m) * (1 + 0.006 * Math.sin(PI2 * Math.max(0, t - T.glide[1]) / 3.2));
    this.logo.transform = 'translate(' + (this.from.dx * m).toFixed(1) + 'px,' + (this.from.dy * m).toFixed(1) + 'px) scale(' + k.toFixed(4) + ')';
    /* the line, word by word (as the hero does), then the description and the calls to action */
    this.words.forEach((s, i) => {
      const w = RISE(seg(t, T.words + i * 0.065, T.words + i * 0.065 + 0.4));
      s.opacity = w.toFixed(3);
      s.filter = w < 1 ? 'blur(' + (12 * (1 - w)).toFixed(2) + 'px)' : 'none';
      s.transform = 'translateY(' + (24 * (1 - w)).toFixed(2) + 'px)';
    });
    const u = RISE(seg(t, T.sub, T.sub + 0.42));
    this.sub.opacity = u.toFixed(3);
    this.sub.transform = 'translateY(' + (20 * (1 - u)).toFixed(2) + 'px)';
    [[this.btn, T.cta[0]]].forEach(([s, a]) => {
      const c = RISE(seg(t, a, a + 0.42));
      s.opacity = c.toFixed(3);
      s.transform = 'translateY(' + (20 * (1 - c)).toFixed(2) + 'px)';
    });
  },
});
